import java.util.*;

class Solution {
    public int factorial(int n) {
        return factorialFrom(n, 1);
    }

    private int factorialFrom(int n, int acc) {
        if (n <= 1) {
            return acc;
        }
        return factorialFrom(n - 1, acc * n);
    }
}

import java.util.*;

class Solution {
    public int factorial(int n) {
        int answer = 1;
        for (int value = 2; value <= n; value++) {
            answer *= value;
        }
        return answer;
    }
}

